class URLOper(object):
    @staticmethod
    def get_page_content_as_list(url):
        """
        Method returns content of page in url path as list of strings
        :param url string
        """
        try:
            f = urlopen(url)
            html = f.readlines()
            f.close()
            return html
        except Exception as e:
            raise Exception("Problem with {}\n {}".format(url, e))

    @staticmethod
    def get_page_content_as_string(url):
        """
        Method returns content of page in url path
        :param url string
        """
        try:
            f = urlopen(url)
            html = f.read()
            f.close()
            return html
        except Exception as e:
            raise Exception("Problem with {}\n {}".format(url, e))

    @staticmethod
    def download(url, file_name):
        """
        Method downloads file from path and saves it as file_name
        :param url, file_name strings
        """
        logger.console(("Download package from {} as {}\n".format(url, file_name)))
        try:
            f = URLopener()
            f.retrieve(url, file_name)
        except Exception as e:
            logger.console(('INF: Problem with downloading from: {}\n{}'.format(url, e)))
            # raise Exception('Problem with downloading: {}\n{}'.format(url, e))


class JenkinsApi(object):
    @staticmethod
    def get_json_api(url):
        """
        Returns api for jenkins url
        """
        api_url = "/".join([url, "api/json?pretty=true"])
        json_as_string = URLOper.get_page_content_as_string(api_url)
        return json.JSONDecoder().decode(json_as_string)

    @staticmethod
    def get_xml_api(url):
        """
        Returns api for jenkins url
        """
        api_url = "/".join([url, "api/xml?pretty=true"])
        string = URLOper.get_page_content_as_string(api_url)
        abstract_tree = etree.fromstring(string)
        return abstract_tree


class TldaDownloader:
    jenkins_root = "http://wrling23.emea.nsn-net.net:8080/job/build.fsmr3"

    def __init__(self, isar):
        logger.console("Running downloader for L3 decoder\n")
        self.isar_num = isar

    def _get_latest_isar_num(self):
        json = JenkinsApi.get_json_api("http://wrling23.emea.nsn-net.net:8080/job/build.fsmr3/lastSuccessfulBuild/")
        string = json['description']
        return string[(string.find("artifact/") + len("artifact/")):string.find(".html")]

    def _find_isar(self):
        if self.isar_num == '':
            self.isar_num = self._get_latest_isar_num()
        self.isar_num = "FL00" + self.isar_num[4:]

    def _get_url_for_artifact(self):
        return "/".join(
            [
                self.jenkins_root,
                self.isar_num[-5:],
                "artifact/build",
                self.isar_num + "_Technical_Log_Decoder_Analyzer_linux_fsmr3.zip",
            ]
        )

    def get(self):
        """
        Function that download , unpacking and removing not important files
        """
        self._find_isar()
        package_addr = self._get_url_for_artifact()
        URLOper.download(package_addr, "/tmp/archive.zip")
        self._unpack("/tmp/archive.zip", "/tmp/")
        self._clean()
        logger.console("Done\n")

    def _unpack(self, file_name, outpath="."):
        logger.console(("Unpacking {}, to {}\n".format(file_name, outpath)))
        f = open(file_name, 'rb')
        with zipfile.ZipFile(file_name, "r") as z:
            for name in z.namelist():
                z.extract(name, outpath)
        f.close()

    def _clean(self):
        logger.console("Removing not important files\n")
        os.remove("/tmp/archive.zip")
